<?php
namespace Modules\Analytics\Services;
use Core\database\DB;use RuntimeException;
class AdminAccessCatalogService{
 public function catalog():array{$roles=[];foreach(DB::table('access_system_roles')->whereNull('deleted_at')->orderBy('scope')->orderBy('sort_order')->orderBy('name')->get()as$r){$id=(int)$r['role_id'];$roles[]=['id'=>$id,'parentId'=>$r['parent_role_id']?(int)$r['parent_role_id']:null,'name'=>$r['name'],'type'=>$r['type'],'level'=>(int)$r['level'],'scope'=>$r['scope'],'color'=>$r['color']?:'#4f46e5','sortOrder'=>(int)$r['sort_order'],'translations'=>$this->translations('access_system_roles',$id),'permissionIds'=>array_map(fn($x)=>(int)$x['permission_id'],DB::table('access_system_role_permissions')->where('role_id',$id)->whereNull('deleted_at')->get())];}$permissions=[];foreach(DB::table('access_system_permissions')->whereNull('deleted_at')->orderBy('scope')->orderBy('resource')->orderBy('action')->get()as$p){$id=(int)$p['permission_id'];$permissions[]=['id'=>$id,'name'=>$p['name'],'resource'=>$p['resource'],'action'=>$p['action'],'type'=>$p['type'],'group'=>$p['group_name'],'scope'=>$p['scope'],'risk'=>(int)$p['risk_level'],'approval'=>$p['approval'],'translations'=>$this->translations('access_system_permissions',$id)];}return['roles'=>$roles,'permissions'=>$permissions];}
 public function saveRole(int$actor,?int$id,array$d):int{return transaction(function()use($actor,$id,$d){$name=$this->name($d['name']??'');$level=max(1,min(3,(int)($d['level']??1)));$scope=$this->one($d['scope']??'',['platform','website','academy','branch','self'],'دامنه نقش');$type=$this->one($d['type']??'',['system','academy','other'],'نوع نقش');$parent=!empty($d['parentId'])?(int)$d['parentId']:null;$existing=DB::table('access_system_roles')->where('name',$name)->whereNull('deleted_at')->first();if($existing&&(!$id||(int)$existing['role_id']!==$id))throw new RuntimeException('نام نقش تکراری است.');$now=date('Y-m-d H:i:s');$v=['parent_role_id'=>$parent,'name'=>$name,'type'=>$type,'level'=>$level,'scope'=>$scope,'color'=>preg_match('/^#[0-9a-fA-F]{6}$/',(string)($d['color']??''))?$d['color']:'#4f46e5','sort_order'=>max(0,min(127,(int)($d['sortOrder']??0))),'updated_at'=>$now,'updated_by'=>$actor,'deleted_at'=>null,'deleted_by'=>null];if($id){$this->role($id);DB::table('access_system_roles')->where('role_id',$id)->update($v);}else$id=(int)DB::table('access_system_roles')->insertGetId($v+['created_at'=>$now,'created_by'=>$actor]);$this->saveTranslations('access_system_roles',$id,$actor,$d['translations']??[]);$this->syncRolePermissions($id,$actor,(array)($d['permissionIds']??[]));return$id;});}
 public function savePermission(int$actor,?int$id,array$d):int{return transaction(function()use($actor,$id,$d){$resource=$this->name($d['resource']??'');$action=$this->name($d['action']??'');$name=$resource.'.'.$action;$existing=DB::table('access_system_permissions')->where('name',$name)->whereNull('deleted_at')->first();if($existing&&(!$id||(int)$existing['permission_id']!==$id))throw new RuntimeException('این مجوز قبلاً تعریف شده است.');$scope=$this->one($d['scope']??'',['platform','website','academy','branch','self'],'دامنه مجوز');$group=in_array($d['group']??'',['website','academy'],true)?$d['group']:($scope==='academy'||$scope==='branch'?'academy':'website');$now=date('Y-m-d H:i:s');$v=['name'=>$name,'resource'=>$resource,'action'=>$action,'type'=>$this->one($d['type']??'sidebar',['menu','sidebar','topbar','header'],'نوع مجوز'),'group_name'=>$group,'scope'=>$scope,'risk_level'=>max(1,min(5,(int)($d['risk']??1))),'approval'=>$this->one($d['approval']??'confirm',['confirm','pending'],'وضعیت تأیید'),'updated_at'=>$now,'updated_by'=>$actor,'deleted_at'=>null,'deleted_by'=>null];if($id){$this->permission($id);DB::table('access_system_permissions')->where('permission_id',$id)->update($v);}else$id=(int)DB::table('access_system_permissions')->insertGetId($v+['created_at'=>$now,'created_by'=>$actor]);$this->saveTranslations('access_system_permissions',$id,$actor,$d['translations']??[]);return$id;});}
 public function deleteRole(int$actor,int$id):void{$this->role($id);if(DB::table('user_roles')->where('role_id',$id)->whereNull('deleted_at')->first())throw new RuntimeException('این نقش به کاربر فعال اختصاص دارد و قابل حذف نیست.');$now=date('Y-m-d H:i:s');DB::table('access_system_roles')->where('role_id',$id)->update(['deleted_at'=>$now,'deleted_by'=>$actor]);DB::table('access_system_role_permissions')->where('role_id',$id)->whereNull('deleted_at')->update(['deleted_at'=>$now,'deleted_by'=>$actor]);}
 public function deletePermission(int$actor,int$id):void{$this->permission($id);if(DB::table('user_permissions')->where('permission_id',$id)->whereNull('deleted_at')->first())throw new RuntimeException('این مجوز مستقیماً به کاربر فعال اختصاص دارد.');$now=date('Y-m-d H:i:s');DB::table('access_system_permissions')->where('permission_id',$id)->update(['deleted_at'=>$now,'deleted_by'=>$actor]);DB::table('access_system_role_permissions')->where('permission_id',$id)->whereNull('deleted_at')->update(['deleted_at'=>$now,'deleted_by'=>$actor]);}
 private function syncRolePermissions(int$id,int$actor,array$ids):void{$ids=array_values(array_unique(array_map('intval',$ids)));$valid=array_map(fn($x)=>(int)$x['permission_id'],DB::table('access_system_permissions')->whereNull('deleted_at')->get());if(array_diff($ids,$valid))throw new RuntimeException('مجوز نامعتبر در نقش انتخاب شده است.');$now=date('Y-m-d H:i:s');foreach(DB::table('access_system_role_permissions')->where('role_id',$id)->get()as$r){$active=in_array((int)$r['permission_id'],$ids,true);DB::table('access_system_role_permissions')->where('role_permission_id',(int)$r['role_permission_id'])->update($active?['deleted_at'=>null,'deleted_by'=>null,'updated_at'=>$now,'updated_by'=>$actor]:['deleted_at'=>$now,'deleted_by'=>$actor]);}$known=array_map(fn($x)=>(int)$x['permission_id'],DB::table('access_system_role_permissions')->where('role_id',$id)->get());foreach(array_diff($ids,$known)as$pid)DB::table('access_system_role_permissions')->insert(['role_id'=>$id,'permission_id'=>$pid,'created_at'=>$now,'created_by'=>$actor,'updated_at'=>$now,'updated_by'=>$actor]);}
 private function translations(string$table,int$id):array{$out=['fa'=>[],'en'=>[]];foreach(DB::table('f_translations')->where('table_name',$table)->where('table_id',$id)->whereNull('deleted_at')->get()as$t)if(isset($out[$t['locale']]))$out[$t['locale']][$t['field']]=$t['value'];return$out;}
 private function saveTranslations(string$table,int$id,int$actor,array$data):void{foreach(['fa','en']as$locale)foreach(['title','summary','description']as$field){$value=trim((string)($data[$locale][$field]??''));if($value==='')throw new RuntimeException("$field برای زبان $locale الزامی است.");$row=DB::table('f_translations')->where('table_name',$table)->where('table_id',$id)->where('locale',$locale)->where('field',$field)->first();$now=date('Y-m-d H:i:s');$v=['value'=>$value,'version'=>1,'updated_at'=>$now,'updated_by'=>$actor,'deleted_at'=>null,'deleted_by'=>null];if($row)DB::table('f_translations')->where('translation_id',(int)$row['translation_id'])->update($v);else DB::table('f_translations')->insert(['table_name'=>$table,'table_id'=>$id,'locale'=>$locale,'field'=>$field,'created_at'=>$now,'created_by'=>$actor]+$v);}}
 private function name(mixed$v):string{$v=trim((string)$v);if(!preg_match('/^[a-z][a-z0-9_.]{1,99}$/',$v))throw new RuntimeException('نام سیستمی باید انگلیسی و شامل حروف کوچک، عدد، نقطه یا زیرخط باشد.');return$v;}private function one(mixed$v,array$a,string$l):string{if(!in_array($v,$a,true))throw new RuntimeException("$l معتبر نیست.");return$v;}private function role(int$id):array{$r=DB::table('access_system_roles')->where('role_id',$id)->whereNull('deleted_at')->first();if(!$r)throw new RuntimeException('نقش یافت نشد.');return$r;}private function permission(int$id):array{$r=DB::table('access_system_permissions')->where('permission_id',$id)->whereNull('deleted_at')->first();if(!$r)throw new RuntimeException('مجوز یافت نشد.');return$r;}
}
